function playlistSection(title,type){const arr=type==='youtube'?S.youtubePlaylists:S.spotifyPlaylists;return `<section class="playlist-section-v29"><div class="kicker">${title.toUpperCase()}</div><div class="block-note">${type==='youtube'?'Saved links open in the official YouTube/YouTube Music handler to avoid WebView player Error 153.':'Saved Spotify playlist links. OAuth is not faked; this beta uses link mode.'}</div><button class="manage-btn-v29" data-addplaylist29="${type}" style="min-height:52px">+ ADD PLAYLIST LINK</button><div class="playlist-list-v29">${arr.map((p,i)=>`<button class="playlist-v29" data-openplaylist29="${type}" data-idx="${i}" style="color:inherit;text-align:left"><span class="thumb">${type==='youtube'?'▶':'●'}</span><span><b>${esc2(p.name)}</b><small>${esc2(p.url)}</small></span><button data-delplaylist29="${type}" data-idx="${i}">×</button></button>`).join('')}</div></section>`}
