function showProfile29(){const r=race(),p=r&&S.race.targetTime&&C?C.paceTargets(r,S.race.targetTime):null;sheet('Profile',`<section class="profile-block-v29"><div class="kicker">${esc2(S.name)} · ADAPTIVE ATHLETE</div><div class="profile-goals-v29">${S.goals.map(g=>`<span>${esc2(g)}</span>`).join('')}</div></section><section class="profile-block-v29">${[['Training type',S.trainingSystems.join(' + ')],['Race target',r?`${r} · ${S.race.targetTime}${p?' · '+C.formatClock(p.race)+'/km':''}`:'None'],['Race date',S.race.raceDate||'Not set'],['Training days',S.days],['Experience',S.experience],['Equipment',S.equipment],['Injuries',S.injuries.join(', ')||'None'],['Exercises',`${countEnabled()} / ${catalog().length}`]].map(x=>`<div class="profile-row-v29"><span>${x[0]}</span><b>${esc2(x[1])}</b></div>`).join('')}</section><div class="profile-actions-v29"><button data-prof29="goals">Edit Goals / Training Type</button><button data-prof29="exercise">Manage Exercises</button><button data-prof29="recover">Recovery / Injuries</button><button data-prof29="fuel">Nutrition & Food Profile</button><button data-prof29="drive">Music / DRIVE</button><button data-prof29="progress">Progress</button><button data-prof29="reset" style="color:var(--danger)">Start Completely Over</button></div>`);$$('[data-prof29]',$('#sheetCard')).forEach(b=>b.onclick=()=>{const k=b.dataset.prof29;if(k==='goals'){closeSheet();showBuilder(0)}if(k==='exercise')showExerciseManager(false);if(k==='recover')showRecover();if(k==='fuel'){closeSheet();showMain('fuel')}if(k==='drive')showDrive29();if(k==='progress')showProgress();if(k==='reset'){localStorage.removeItem(KEY);location.reload()}})}
